contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: create a grant proposal and then call voteProposal;
    // assert that mapPID_votes[proposalID] after voting is >= its value just before voting
    function run(address recipient, uint amount) public payable {
        require(recipient != address(0));
        // create a new grant proposal (increments proposalCount)
        c.newGrantProposal(recipient, amount);
        // read the latest proposalCount to identify the proposal we just created
        uint pid = c.proposalCount();
        // read votes before voting
        uint votesBefore = c.mapPID_votes(pid);
        // perform voteProposal and catch potential revert
        bool reverted = false;
        uint returnedWeight = 0;
        try c.voteProposal(pid) returns (uint w) {
            returnedWeight = w;
        } catch {
            reverted = true;
        }
        // read votes after voting
        uint votesAfter = c.mapPID_votes(pid);

        // General rule: if the vote call did not revert, the recorded votes for the proposal did not decrease.
        // If it reverted, we cannot observe a state change, so require that votesAfter equals votesBefore.
        // This yields a single assert over observable state and revert flag.
        if (reverted) {
            assert(votesAfter == votesBefore);
        } else {
            assert(votesAfter >= votesBefore);
        }
    }

    // receive to allow this contract to hold Ether if needed by tests
    receive() external payable {}
}

