    constructor(C _c) { c = _c; }

    // single public entry that performs the property check
    function run(address recipient, uint amount) public payable {
        require(recipient != address(0), "recipient nonzero"); // avoid trivial zero-address proposals that other rules might depend on
        // read proposalCount before
        uint beforeCount = c.proposalCount();

        // create a new grant proposal (top-level state-changing call)
        c.newGrantProposal(recipient, amount);

        // read proposalCount after
        uint afterCount = c.proposalCount();

        // read stored grant details for the new proposal id
        uint newPID = afterCount;
